-- 인덱스를 못 탄다

@Test
void 인덱스() {
    em.createNativeQuery("create index idx_username on member(username)")
            .executeUpdate();
    for (int i = 0; i < 20000; i++) em.persist(new Member("p" + i, 10));
    em.flush(); em.clear();

    List<?> a = em.createNativeQuery(
            "explain analyze select * from member where username = 'p100'")
        .getResultList();
    System.out.println("그대로:\n" + a.get(0));

    List<?> b = em.createNativeQuery(
            "explain analyze select * from member" +
            " where lower(username) = 'p100'").getResultList();
    System.out.println("lower:\n" + b.get(0));
}

그대로:
SELECT * FROM PUBLIC.MEMBER
    /* PUBLIC.IDX_USERNAME: USERNAME = 'p100' */
    /* scanCount: 2 */
WHERE USERNAME = 'p100'

lower:
SELECT * FROM PUBLIC.MEMBER
    /* PUBLIC.MEMBER.tableScan */
    /* scanCount: 20013 */
WHERE LOWER(USERNAME) = 'p100'

--   2 대 20013 이다
--   4.6절에서 정렬로 본 그 문제다


-- 방언에 함수를 등록한다

public class MyH2Dialect extends H2Dialect {

    @Override
    public void initializeFunctionRegistry(
            FunctionContributions contributions) {
        super.initializeFunctionRegistry(contributions);
        contributions.getFunctionRegistry()
                .registerPattern("initcap", "upper(substring(?1, 1, 1)) || "
                        + "lower(substring(?1, 2))",
                        contributions.getTypeConfiguration()
                                .getBasicTypeRegistry()
                                .resolve(StandardBasicTypes.STRING));
    }
}

