-- 5장을 닫는다

@Test
void 5장_결론() {
    em.clear();
    List<MemberDto> r = queryFactory
            .select(new QMemberDto(
                    member.username.upper(),
                    member.age))
            .from(member)
            .leftJoin(member.team, team)
            .where(usernameStarts("m"), ageGoe(20), teamNameEq(null))
            .orderBy(member.age.desc())
            .limit(3)
            .fetch();

    r.forEach(d -> System.out.println(d.getUsername() + " " + d.getAge()));
}

